CREATE UNIQUE INDEX idx_automation_bindings_active ON automation_continuity_bindings(definition_id, continuity_key) WHERE status='active';
CREATE INDEX idx_automation_bindings_seed_active ON automation_continuity_bindings(definition_id,seed_id) WHERE status='active' AND seed_id<>'';
CREATE INDEX idx_automation_review_edges_host ON automation_review_request_edges(definition_id, host, active);
CREATE INDEX idx_automation_runs_definition_created ON automation_runs(definition_id, created_at DESC);
CREATE INDEX idx_automation_runs_seed_created ON automation_runs(seed_id,created_at DESC,id DESC) WHERE seed_id<>'';
CREATE INDEX idx_automation_runs_session_created ON automation_runs(session_id, created_at DESC, id DESC);
CREATE INDEX idx_automation_runs_ticket_created ON automation_runs(ticket_id, created_at DESC, id DESC);
CREATE INDEX idx_automode_denials_recent ON automode_denials(id DESC);
CREATE UNIQUE INDEX idx_automode_proposals_pending_ask ON automode_proposals(kind, target, value, proposed_by) WHERE state = 'pending';
CREATE INDEX idx_automode_proposals_state ON automode_proposals(state, id);
CREATE INDEX idx_bus_events_name ON bus_events(name, seq);
CREATE INDEX idx_bus_events_subject ON bus_events(subject, seq);
CREATE INDEX idx_chief_dispatches_chief_created ON chief_of_staff_dispatches(chief_session_id, created_at DESC);
CREATE INDEX idx_crew_profiles_profile ON crew_profiles(profile_id);
CREATE UNIQUE INDEX idx_delegation_operations_active_ticket ON delegation_operations(ticket_id) WHERE ticket_id != '' AND state IN ('accepted', 'preparing');
CREATE INDEX idx_delegation_operations_operation_id ON delegation_operations(operation_id);
CREATE INDEX idx_delegation_operations_session ON delegation_operations(session_id);
CREATE INDEX idx_desktop_panes_desktop ON desktop_panes(desktop_id);
CREATE INDEX idx_desktop_panes_session ON desktop_panes(session_id, created_at);
CREATE INDEX idx_desktops_profile ON desktops(profile_id, order_key);
CREATE UNIQUE INDEX idx_document_collections_address ON document_collections(namespace, collection);
CREATE INDEX idx_file_activity_last_at ON file_activity(last_at DESC);
CREATE INDEX idx_garden_seed_watches_seed ON garden_seed_watches(seed_id, watcher_session_id);
CREATE INDEX idx_inbox_source ON inbox_items(kind,source_id,address);
CREATE INDEX idx_inbox_unread ON inbox_items(address,created_at,id) WHERE read_at = '';
CREATE UNIQUE INDEX idx_inbox_unread_key ON inbox_items(address,kind,coalesce_key) WHERE coalesce_key != '' AND read_at = '';
CREATE INDEX idx_jobs_eligible ON jobs(state, scheduled_at, priority DESC);
CREATE UNIQUE INDEX idx_jobs_unique_key ON jobs(kind, unique_key) WHERE unique_key <> '';
CREATE INDEX idx_notifications_created ON notifications(created_at);
CREATE INDEX idx_peer_messages_sender_created ON peer_messages(sender_session_id, created_at);
CREATE INDEX idx_presentation_comments_round ON presentation_comments(round_id);
CREATE INDEX idx_presentations_session ON presentations(session_id);
CREATE UNIQUE INDEX idx_profiles_live_name ON profiles(name) WHERE deleted_at = '';
CREATE UNIQUE INDEX idx_prs_host_repo_number ON prs(host, repo, number);
CREATE INDEX idx_pull_request_watches_pr ON pull_request_watches(pr_id,address);
CREATE INDEX idx_session_pull_requests_session ON session_pull_requests(session_id, created_at DESC);
CREATE INDEX idx_sessions_closed_at ON sessions(closed_at, id);
CREATE INDEX idx_sessions_profile_id ON sessions(profile_id);
CREATE INDEX idx_sessions_repository ON sessions(repository);
CREATE INDEX idx_sessions_succeeds ON sessions(succeeds) WHERE succeeds != '';
CREATE INDEX idx_workflow_agent_calls_run_id ON workflow_agent_calls(run_id, id ASC);
CREATE INDEX idx_workflow_runs_created_at ON workflow_runs(created_at DESC);
CREATE INDEX idx_workflow_runs_status ON workflow_runs(status);
CREATE INDEX idx_worktree_sweep_log_at ON worktree_sweep_log(at DESC, id DESC);
CREATE INDEX launch_desktops_desktop ON launch_desktops(desktop_id);
CREATE TABLE authors ( author TEXT PRIMARY KEY, muted INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE "automation_continuity_bindings" ( id TEXT PRIMARY KEY, definition_id INTEGER NOT NULL, continuity_key TEXT NOT NULL, ticket_id TEXT NOT NULL, session_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', released_reason TEXT NOT NULL DEFAULT '', released_at TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, seed_id TEXT NOT NULL DEFAULT '', origin_run_id TEXT NOT NULL DEFAULT '', profile_id TEXT NOT NULL DEFAULT '', FOREIGN KEY(definition_id) REFERENCES automation_definitions(id) );
CREATE TABLE "automation_definitions" ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, enabled INTEGER NOT NULL, revision INTEGER NOT NULL, spec_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT NOT NULL DEFAULT '' , profile_id TEXT NOT NULL DEFAULT '');
CREATE TABLE "automation_occurrences" ( id TEXT PRIMARY KEY, definition_id INTEGER NOT NULL, provider TEXT NOT NULL, occurrence_key TEXT NOT NULL, subject_key TEXT NOT NULL DEFAULT '', observed_at TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(definition_id, provider, occurrence_key), FOREIGN KEY(definition_id) REFERENCES automation_definitions(id) );
CREATE TABLE "automation_provider_cursors" ( definition_id INTEGER NOT NULL, provider TEXT NOT NULL, scope TEXT NOT NULL, observed_at TEXT NOT NULL, PRIMARY KEY(definition_id, provider, scope), FOREIGN KEY(definition_id) REFERENCES automation_definitions(id) );
CREATE TABLE "automation_review_request_edges" ( definition_id INTEGER NOT NULL, subject_key TEXT NOT NULL, host TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 0, cycle INTEGER NOT NULL DEFAULT 0, last_observed_at TEXT NOT NULL, updated_at TEXT NOT NULL, baseline_cycle INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(definition_id, subject_key), FOREIGN KEY(definition_id) REFERENCES automation_definitions(id) );
CREATE TABLE "automation_runs" ( id TEXT PRIMARY KEY, definition_id INTEGER NOT NULL, occurrence_id TEXT NOT NULL UNIQUE, definition_revision INTEGER NOT NULL, snapshot_json TEXT NOT NULL, state TEXT NOT NULL, cancel_reason TEXT NOT NULL DEFAULT '', attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT NOT NULL DEFAULT '', ticket_id TEXT NOT NULL, session_id TEXT NOT NULL, resolved_location_json TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, delivered_at TEXT NOT NULL DEFAULT '', seed_id TEXT NOT NULL DEFAULT '', profile_id TEXT NOT NULL DEFAULT '', FOREIGN KEY(definition_id) REFERENCES automation_definitions(id), FOREIGN KEY(occurrence_id) REFERENCES automation_occurrences(id) );
CREATE TABLE automode_config ( id INTEGER PRIMARY KEY CHECK (id = 1), enabled_default INTEGER NOT NULL DEFAULT 1, environment TEXT NOT NULL DEFAULT '[]', updated_at TEXT NOT NULL DEFAULT '' , approval_policy TEXT NOT NULL DEFAULT 'on-request', sandbox_mode TEXT NOT NULL DEFAULT 'workspace-write', rules TEXT NOT NULL DEFAULT '[]', network TEXT NOT NULL DEFAULT '', legacy_patterns TEXT NOT NULL DEFAULT '[]', guardian TEXT NOT NULL DEFAULT '{}');
CREATE TABLE automode_denials ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL DEFAULT '', tool TEXT NOT NULL DEFAULT '', signature TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL , rule TEXT NOT NULL DEFAULT '');
CREATE TABLE automode_proposals ( id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, target TEXT NOT NULL DEFAULT '', value TEXT NOT NULL, proposed_by TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL, resolved_at TEXT NOT NULL DEFAULT '' );
CREATE TABLE bus_consumers ( name TEXT PRIMARY KEY, cursor INTEGER NOT NULL DEFAULT 0, filter TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT '' );
CREATE TABLE bus_events ( seq INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, subject TEXT NOT NULL DEFAULT '', payload TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL );
CREATE TABLE chief_of_staff_dispatches ( id TEXT PRIMARY KEY, chief_session_id TEXT NOT NULL, session_id TEXT NOT NULL UNIQUE, brief TEXT NOT NULL, label TEXT NOT NULL, agent TEXT NOT NULL, directory TEXT NOT NULL, branch TEXT NOT NULL DEFAULT '', latest_report TEXT NOT NULL DEFAULT '', reported_at TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL , structured_report_json TEXT NOT NULL DEFAULT '', closed_state TEXT NOT NULL DEFAULT '', profile_id TEXT NOT NULL DEFAULT '');
CREATE TABLE command_usage ( profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, command_id TEXT NOT NULL, score REAL NOT NULL, last_used_at TEXT NOT NULL, PRIMARY KEY(profile_id, command_id) );
CREATE TABLE crew_profiles ( member_id TEXT PRIMARY KEY, profile_id TEXT NOT NULL );
CREATE TABLE delegation_operations ( request_id TEXT PRIMARY KEY, operation_id TEXT NOT NULL UNIQUE, request_json TEXT NOT NULL, state TEXT NOT NULL, progress TEXT NOT NULL, session_id TEXT NOT NULL, ticket_id TEXT NOT NULL DEFAULT '', worktree_path TEXT NOT NULL DEFAULT '', worktree_owned INTEGER NOT NULL DEFAULT 0, result_json TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL , worktree_token TEXT NOT NULL DEFAULT '', chief_session_id TEXT NOT NULL DEFAULT '', resolved_preferences TEXT NOT NULL DEFAULT '', directory TEXT NOT NULL DEFAULT '', branch TEXT NOT NULL DEFAULT '', base_commit TEXT NOT NULL DEFAULT '', handoff_note_id TEXT NOT NULL DEFAULT '', failure_code TEXT NOT NULL DEFAULT '', handover_seed_rev INTEGER NOT NULL DEFAULT 0, handover_tender_session TEXT NOT NULL DEFAULT '', handover_tender_member TEXT NOT NULL DEFAULT '', parent_seed_id TEXT NOT NULL DEFAULT '', profile_id TEXT NOT NULL DEFAULT '');
CREATE TABLE delegation_preference_revisions ( revision INTEGER PRIMARY KEY, parent INTEGER, restores INTEGER, config TEXT NOT NULL, origin TEXT NOT NULL DEFAULT '', message TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL );
CREATE TABLE "desktop_panes" ( pane_id TEXT PRIMARY KEY, desktop_id TEXT NOT NULL, kind TEXT NOT NULL, session_id TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'ready', error TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, runtime_id TEXT NOT NULL DEFAULT '' );
CREATE TABLE desktops ( id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', order_key TEXT NOT NULL, tree_json TEXT NOT NULL DEFAULT '', active_pane_id TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL , focus_history TEXT NOT NULL DEFAULT '[]', empty_since TEXT NOT NULL DEFAULT '');
CREATE TABLE document_collections ( id INTEGER PRIMARY KEY AUTOINCREMENT, namespace TEXT NOT NULL, collection TEXT NOT NULL, fields_json TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE endpoints ( id TEXT PRIMARY KEY, name TEXT NOT NULL, ssh_target TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, instance TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE file_activity ( path TEXT NOT NULL, source TEXT NOT NULL, session_id TEXT, last_at TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(path, source) );
CREATE TABLE garden_seed_artifact_observations ( seed_id TEXT PRIMARY KEY, checksum TEXT NOT NULL, event_seq INTEGER NOT NULL UNIQUE, observed_at TEXT NOT NULL );
CREATE TABLE garden_seed_event_receipts ( event_seq INTEGER PRIMARY KEY, handled_at TEXT NOT NULL );
CREATE TABLE garden_seed_event_sources ( source_kind TEXT NOT NULL, source_id TEXT NOT NULL, event_name TEXT NOT NULL, event_seq INTEGER NOT NULL UNIQUE, PRIMARY KEY (source_kind, source_id, event_name) );
CREATE TABLE garden_seed_watches ( watcher_session_id TEXT NOT NULL, seed_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(watcher_session_id, seed_id) );
CREATE TABLE inbox_delivery (address TEXT PRIMARY KEY, outstanding_at TEXT NOT NULL);
CREATE TABLE inbox_items ( id TEXT PRIMARY KEY, address TEXT NOT NULL, kind TEXT NOT NULL, source_id TEXT NOT NULL DEFAULT '', coalesce_key TEXT NOT NULL DEFAULT '', hint TEXT NOT NULL DEFAULT '', text TEXT NOT NULL DEFAULT '', bell_name TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, attempted_at TEXT NOT NULL DEFAULT '', notified_at TEXT NOT NULL DEFAULT '', read_at TEXT NOT NULL DEFAULT '', read_by TEXT NOT NULL DEFAULT '', CHECK(read_at = '' OR notified_at != ''));
CREATE TABLE jobs ( id TEXT PRIMARY KEY, kind TEXT NOT NULL, unique_key TEXT NOT NULL DEFAULT '', priority INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL DEFAULT '', result TEXT NOT NULL DEFAULT '', state TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 0, scheduled_at TEXT NOT NULL, last_error TEXT NOT NULL DEFAULT '', requeued INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL , last_diagnostic TEXT NOT NULL DEFAULT '');
CREATE TABLE kept_conversation_pins ( agent TEXT NOT NULL, resume_id TEXT NOT NULL, session_id TEXT NOT NULL, pinned_at TEXT NOT NULL, PRIMARY KEY (agent, resume_id) );
CREATE TABLE kept_conversations ( resume_id TEXT NOT NULL, agent TEXT NOT NULL, source_path TEXT NOT NULL, bytes INTEGER NOT NULL, stored_bytes INTEGER NOT NULL, copied_at TEXT NOT NULL, released_at TEXT NOT NULL DEFAULT '', deleted_at TEXT NOT NULL DEFAULT '', deleted_by TEXT NOT NULL DEFAULT '', PRIMARY KEY (agent, resume_id) );
CREATE TABLE launch_desktops ( kind TEXT NOT NULL CHECK(kind IN ('automation', 'crew')), item_id TEXT NOT NULL, desktop_id TEXT NOT NULL, confirmed INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (kind, item_id) );
CREATE TABLE markdown_annotation_drafts ( path TEXT PRIMARY KEY, annotations_json TEXT NOT NULL, generation INTEGER NOT NULL, tombstone_generation INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL );
CREATE TABLE notifications ( id TEXT PRIMARY KEY, kind TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', detail TEXT NOT NULL DEFAULT '', source_kind TEXT NOT NULL DEFAULT '', source_id TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, read_at TEXT NOT NULL DEFAULT '' , severity TEXT NOT NULL DEFAULT 'info', trigger TEXT NOT NULL DEFAULT '', impact TEXT NOT NULL DEFAULT '', cause TEXT NOT NULL DEFAULT '', diagnostic TEXT NOT NULL DEFAULT '', actions_json TEXT NOT NULL DEFAULT '');
CREATE TABLE peer_messages ( id TEXT PRIMARY KEY, sender_session_id TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL );
CREATE TABLE pr_interactions ( pr_id TEXT PRIMARY KEY, last_visited_at TEXT, last_approved_at TEXT, last_seen_sha TEXT, last_seen_comment_count INTEGER , last_seen_ci_status TEXT);
CREATE TABLE presentation_comments ( id TEXT PRIMARY KEY, round_id TEXT NOT NULL REFERENCES presentation_rounds(id) ON DELETE CASCADE, filepath TEXT NOT NULL, line_start INTEGER NOT NULL, line_end INTEGER NOT NULL, side TEXT NOT NULL, content TEXT NOT NULL, author TEXT NOT NULL DEFAULT 'user', created_at TEXT NOT NULL );
CREATE TABLE presentation_rounds ( id TEXT PRIMARY KEY, presentation_id TEXT NOT NULL REFERENCES presentations(id) ON DELETE CASCADE, seq INTEGER NOT NULL, manifest_yaml TEXT NOT NULL, base_sha TEXT NOT NULL, head_sha TEXT NOT NULL, created_at TEXT NOT NULL, submitted_at TEXT, verdict TEXT, UNIQUE(presentation_id, seq) );
CREATE TABLE presentations ( id TEXT PRIMARY KEY, session_id TEXT NOT NULL, ticket_id TEXT, title TEXT NOT NULL, kind TEXT NOT NULL, repo_path TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL , address TEXT NOT NULL DEFAULT '');
CREATE TABLE profile_migration ( id INTEGER PRIMARY KEY CHECK (id = 1), schema_version INTEGER NOT NULL, phase TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, imported_groups TEXT NOT NULL DEFAULT '', draft TEXT NOT NULL DEFAULT '' , launch_review_complete INTEGER NOT NULL DEFAULT 0);
CREATE TABLE profiles ( id TEXT PRIMARY KEY, name TEXT NOT NULL, current_desktop_id TEXT NOT NULL DEFAULT '', last_used_at TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, deleted_at TEXT NOT NULL DEFAULT '' , chief_session_id TEXT NOT NULL DEFAULT '');
CREATE TABLE prs ( id TEXT PRIMARY KEY, repo TEXT NOT NULL, number INTEGER NOT NULL, title TEXT NOT NULL, url TEXT NOT NULL, role TEXT NOT NULL, state TEXT NOT NULL, reason TEXT, last_updated TEXT NOT NULL, last_polled TEXT NOT NULL, muted INTEGER NOT NULL DEFAULT 0, details_fetched INTEGER NOT NULL DEFAULT 0, details_fetched_at TEXT, mergeable INTEGER, mergeable_state TEXT, ci_status TEXT, review_status TEXT , head_sha TEXT, head_branch TEXT, comment_count INTEGER NOT NULL DEFAULT 0, approved_by_me INTEGER NOT NULL DEFAULT 0, heat_state TEXT NOT NULL DEFAULT 'cold', last_heat_activity_at TEXT, author TEXT NOT NULL DEFAULT '', host TEXT NOT NULL DEFAULT 'github.com');
CREATE TABLE pull_request_watches ( address TEXT NOT NULL, session_id TEXT NOT NULL, pr_id TEXT NOT NULL, mode TEXT NOT NULL, reviewer TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, cursor_json TEXT NOT NULL DEFAULT '{}', last_success_at TEXT NOT NULL DEFAULT '',last_error TEXT NOT NULL DEFAULT '',feedback_error TEXT NOT NULL DEFAULT '', outage_active INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(address,pr_id));
CREATE TABLE recent_locations ( path TEXT PRIMARY KEY, last_seen TEXT NOT NULL, use_count INTEGER NOT NULL DEFAULT 1 );
CREATE TABLE repo_integration_branches ( main_repo TEXT PRIMARY KEY, branch TEXT NOT NULL, source TEXT NOT NULL, resolved_at TEXT NOT NULL );
CREATE TABLE repo_merged_branches ( main_repo TEXT NOT NULL, branch TEXT NOT NULL, merged_at TEXT NOT NULL DEFAULT '', number INTEGER NOT NULL DEFAULT 0, url TEXT NOT NULL DEFAULT '', head_sha TEXT NOT NULL DEFAULT '', observed_at TEXT NOT NULL, PRIMARY KEY (main_repo, branch) );
CREATE TABLE repos ( repo TEXT PRIMARY KEY, muted INTEGER NOT NULL DEFAULT 0, collapsed INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE review_comments ( id TEXT PRIMARY KEY, review_id TEXT NOT NULL, filepath TEXT NOT NULL, line_start INTEGER NOT NULL, line_end INTEGER NOT NULL, content TEXT NOT NULL, author TEXT NOT NULL, resolved INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, resolved_by TEXT NOT NULL DEFAULT '', resolved_at TEXT NOT NULL DEFAULT '', FOREIGN KEY (review_id) REFERENCES reviews(id) ON DELETE CASCADE );
CREATE TABLE review_viewed_files ( review_id TEXT NOT NULL, filepath TEXT NOT NULL, viewed_at TEXT NOT NULL, PRIMARY KEY (review_id, filepath), FOREIGN KEY (review_id) REFERENCES reviews(id) ON DELETE CASCADE );
CREATE TABLE reviewer_sessions ( id TEXT PRIMARY KEY, review_id TEXT NOT NULL, commit_sha TEXT NOT NULL, transcript TEXT NOT NULL, started_at TEXT NOT NULL, completed_at TEXT, FOREIGN KEY (review_id) REFERENCES reviews(id) ON DELETE CASCADE );
CREATE TABLE reviews ( id TEXT PRIMARY KEY, branch TEXT NOT NULL, pr_number INTEGER, repo_path TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(repo_path, branch) );
CREATE TABLE schema_migrations ( version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL );
CREATE TABLE session_annotation_drafts ( session_id TEXT PRIMARY KEY, annotations_json TEXT NOT NULL, generation INTEGER NOT NULL, tombstone_generation INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL , note TEXT NOT NULL DEFAULT '');
CREATE TABLE session_exit_screens ( session_id TEXT PRIMARY KEY, text TEXT NOT NULL DEFAULT '', cols INTEGER NOT NULL DEFAULT 0, rows INTEGER NOT NULL DEFAULT 0, exit_code INTEGER NOT NULL DEFAULT 0, exit_signal TEXT NOT NULL DEFAULT '', exited_at TEXT NOT NULL );
CREATE TABLE session_pull_requests ( session_id TEXT NOT NULL, pr_id TEXT NOT NULL, repository TEXT NOT NULL, number INTEGER NOT NULL, url TEXT NOT NULL, created_at TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', draft INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'open', ci_status TEXT NOT NULL DEFAULT '', review_status TEXT NOT NULL DEFAULT '', mergeable_state TEXT NOT NULL DEFAULT '', head_sha TEXT NOT NULL DEFAULT '', head_branch TEXT NOT NULL DEFAULT '', status_fetched_at TEXT NOT NULL DEFAULT '', last_activity_at TEXT NOT NULL DEFAULT '', status_checked_at TEXT NOT NULL DEFAULT '', readiness_state TEXT NOT NULL DEFAULT '', readiness_reason TEXT NOT NULL DEFAULT '', settling_until TEXT NOT NULL DEFAULT '', watch_health TEXT NOT NULL DEFAULT '', watch_error TEXT NOT NULL DEFAULT '', watch_last_checked_at TEXT NOT NULL DEFAULT '', PRIMARY KEY (session_id, pr_id) );
CREATE TABLE session_teardown_tombstones ( session_id TEXT PRIMARY KEY, requested_at TEXT NOT NULL, driver_plugin_name TEXT NOT NULL DEFAULT '', driver_run_id TEXT NOT NULL DEFAULT '', driver_report_seq INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE sessions ( id TEXT PRIMARY KEY, label TEXT NOT NULL, directory TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'idle', state_since TEXT NOT NULL, state_updated_at TEXT NOT NULL, last_seen TEXT NOT NULL , branch TEXT, is_worktree INTEGER NOT NULL DEFAULT 0, main_repo TEXT, agent TEXT NOT NULL DEFAULT 'codex', resume_session_id TEXT NOT NULL DEFAULT '', endpoint_id TEXT, agent_metadata TEXT NOT NULL DEFAULT '', agent_driver_plugin_name TEXT NOT NULL DEFAULT '', agent_driver_run_id TEXT NOT NULL DEFAULT '', agent_driver_report_seq INTEGER NOT NULL DEFAULT 0, closed_intentionally_at TEXT NOT NULL DEFAULT '', launch_intent TEXT NOT NULL DEFAULT '', turn_settled_at TEXT NOT NULL DEFAULT '', turn_opened_at TEXT NOT NULL DEFAULT '', turn_snoozed_until TEXT NOT NULL DEFAULT '', parent_session_id TEXT NOT NULL DEFAULT '', context_window_cap INTEGER NOT NULL DEFAULT 0, activity TEXT NOT NULL DEFAULT '', activity_at TEXT NOT NULL DEFAULT '', activity_cursor TEXT NOT NULL DEFAULT '', session_cost_json TEXT NOT NULL DEFAULT '', last_model_request_at TEXT, transcript_path TEXT NOT NULL DEFAULT '', closed_at TEXT NOT NULL DEFAULT '', closed_by TEXT NOT NULL DEFAULT '', close_reason TEXT NOT NULL DEFAULT '', repository TEXT NOT NULL DEFAULT '', agent_driver_transcript_path TEXT NOT NULL DEFAULT '', launched_at TEXT NOT NULL DEFAULT '', profile_id TEXT NOT NULL DEFAULT '', last_desktop_id TEXT NOT NULL DEFAULT '', succeeds TEXT NOT NULL DEFAULT '');
CREATE TABLE settings ( key TEXT PRIMARY KEY, value TEXT );
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE supervised_parks ( child TEXT PRIMARY KEY, parked_at TEXT NOT NULL, restart_attempt INTEGER NOT NULL DEFAULT 0, exit_at TEXT NOT NULL DEFAULT '', exit_code INTEGER, exit_signal TEXT NOT NULL DEFAULT '', exit_error TEXT NOT NULL DEFAULT '' );
CREATE TABLE tasks ( id TEXT PRIMARY KEY, kind TEXT NOT NULL, subject TEXT NOT NULL, state TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, last_error TEXT NOT NULL DEFAULT '', meta_json TEXT NOT NULL DEFAULT '', requeued INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE workflow_agent_calls ( id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL, ordinal TEXT NOT NULL, label TEXT, phase TEXT, prompt_hash TEXT, schema_hash TEXT, resolved_model TEXT, resolved_harness TEXT, agent_type TEXT, result_json TEXT, status TEXT NOT NULL, error TEXT, result_path TEXT, started_at TEXT, completed_at TEXT, UNIQUE(run_id, ordinal), FOREIGN KEY (run_id) REFERENCES workflow_runs(run_id) ON DELETE CASCADE );
CREATE TABLE workflow_runs ( run_id TEXT PRIMARY KEY, script_path TEXT NOT NULL, script_hash TEXT NOT NULL, args_json TEXT, session_id TEXT, status TEXT NOT NULL, phase TEXT, harness TEXT, result_json TEXT, last_error TEXT, resumable INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, completed_at TEXT , profile_id TEXT NOT NULL DEFAULT '');
CREATE TABLE worktree_sweep_log ( id TEXT PRIMARY KEY, path TEXT NOT NULL, main_repo TEXT NOT NULL, branch TEXT NOT NULL DEFAULT '', action TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', at TEXT NOT NULL );
CREATE TABLE worktrees ( path TEXT PRIMARY KEY, branch TEXT NOT NULL, main_repo TEXT NOT NULL, created_at TEXT NOT NULL , origin TEXT NOT NULL DEFAULT '', pinned_at TEXT NOT NULL DEFAULT '', observed_at TEXT NOT NULL DEFAULT '', head_sha TEXT NOT NULL DEFAULT '', detached INTEGER NOT NULL DEFAULT 0, dirty INTEGER NOT NULL DEFAULT 0, dirty_files INTEGER NOT NULL DEFAULT 0, stashes INTEGER NOT NULL DEFAULT 0, unpushed INTEGER NOT NULL DEFAULT 0, merged_signal TEXT NOT NULL DEFAULT '', prunable INTEGER NOT NULL DEFAULT 0, last_activity_at TEXT NOT NULL DEFAULT '', sweep_status TEXT NOT NULL DEFAULT '', sweep_reason TEXT NOT NULL DEFAULT '', sweep_at TEXT NOT NULL DEFAULT '', refresh_error TEXT NOT NULL DEFAULT '');
CREATE TRIGGER launch_automation_deleted AFTER UPDATE OF deleted_at ON automation_definitions WHEN NEW.deleted_at != '' BEGIN DELETE FROM launch_desktops WHERE kind = 'automation' AND item_id = NEW.id; END;
CREATE TRIGGER launch_review_crew_insert AFTER INSERT ON crew_profiles BEGIN UPDATE profile_migration SET revision = revision + 1 WHERE phase = 'launch_required'; END;
CREATE TRIGGER launch_review_crew_profile AFTER UPDATE ON crew_profiles WHEN OLD.profile_id != NEW.profile_id BEGIN UPDATE profile_migration SET revision = revision + 1 WHERE phase = 'launch_required'; END;
CREATE TRIGGER launch_review_definition_insert AFTER INSERT ON automation_definitions BEGIN UPDATE profile_migration SET revision = revision + 1 WHERE phase = 'launch_required'; END;
CREATE TRIGGER launch_review_definition_update AFTER UPDATE OF name, profile_id, deleted_at ON automation_definitions WHEN OLD.name != NEW.name OR OLD.profile_id != NEW.profile_id OR OLD.deleted_at != NEW.deleted_at BEGIN UPDATE profile_migration SET revision = revision + 1 WHERE phase = 'launch_required'; END;
CREATE TRIGGER launch_review_setting_delete AFTER DELETE ON launch_desktops BEGIN UPDATE profile_migration SET revision = revision + 1 WHERE phase = 'launch_required'; END;
CREATE TRIGGER launch_review_setting_insert AFTER INSERT ON launch_desktops BEGIN UPDATE profile_migration SET revision = revision + 1 WHERE phase = 'launch_required'; END;
CREATE TRIGGER launch_review_setting_update AFTER UPDATE ON launch_desktops BEGIN UPDATE profile_migration SET revision = revision + 1 WHERE phase = 'launch_required'; END;
CREATE TRIGGER remember_remaining_session_desktop AFTER DELETE ON desktop_panes WHEN OLD.session_id != '' AND EXISTS (SELECT 1 FROM desktop_panes WHERE session_id = OLD.session_id) BEGIN UPDATE sessions SET last_desktop_id = (SELECT desktop_id FROM desktop_panes WHERE session_id = OLD.session_id ORDER BY created_at DESC, pane_id DESC LIMIT 1) WHERE id = OLD.session_id; END;
CREATE TRIGGER remember_session_desktop AFTER INSERT ON desktop_panes WHEN NEW.session_id != '' BEGIN UPDATE sessions SET last_desktop_id = (SELECT desktop_id FROM desktop_panes WHERE session_id = NEW.session_id ORDER BY created_at DESC, pane_id DESC LIMIT 1) WHERE id = NEW.session_id; END;
